UPDATE lessons SET title='Year 3, Week 29, Lesson 3: AM and PM', data=json_patch(data,'{"child_mission":"AM times are from midnight to just before noon; PM times are from noon to just before midnight. Context tells which half of the day.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nLabel AM or PM: school starts 9:00; dinner 6:30; bedtime 8:15; sunrise 6:20.\n\nFEEDBACK\nAM; PM; PM; AM (typical).\n\nWATCH FOR\nThinking AM/PM only means morning/night without the noon/midnight boundaries confuses midday times.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSort sixteen events into AM/PM. Write four pairs of the same clock numbers with different AM/PM meanings (e.g. 7:00 AM vs 7:00 PM).\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"AM times are from midnight to just before noon; PM times are from noon to just before midnight. Context tells which half of the day.","lesson_number":3,"lesson_role":"Problem solving","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-NSM-02"],"parent_notes":"Parent: Marking guidance for the independent task: Sort sixteen events into AM/PM. Write four pairs of the same clock numbers with different AM/PM meanings (e.g. 7:00 AM vs 7:00 PM). Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: AM; PM; PM; AM (typical). Reasoning: I used am by attending to pm and explain why it matters rather than copying the worked model.\n\nParent: Written model 2: Common error: Thinking AM/PM only means morning/night without the noon/midnight boundaries confuses midday times. Correction: AM; PM; PM; AM (typical). Why: the correction restores accurate use of am.\n\nParent: Likely misconception: Thinking AM/PM only means morning/night without the noon/midnight boundaries confuses midday times. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses am with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with am, show corrected working, and say why the correction works.\n\nParent: Marking notes: Require new numbers, visible working and named places/values. / Require a real misconception, corrected working and a method reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":3,"explanation":"AM; PM; PM; AM (typical). This matches the lesson skill for am.","options":["Thinking AM/PM only means morning/night without the noon/midnight boundaries confuses midday times.","Ignore the task and invent an unrelated answer.","Copy the worked example and call it independent work.","AM; PM; PM; AM (typical)."],"question":"Label AM or PM: school starts 9:00; dinner 6:30; bedtime 8:15; sunrise 6:20. Which response is most accurate?","type":"multiple_choice"},{"correct_index":1,"explanation":"Thinking AM/PM only means morning/night without the noon/midnight boundaries confuses midday times. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Careful use of pm and explain why it matters with clear evidence.","Thinking AM/PM only means morning/night without the noon/midnight boun